        tree_sum[node] = tree_sum[2 * node] + tree_sum[2 * node + 1];
    }

    long long querySum(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return tree_sum[node];
        int mid = (l + r) / 2;
        long long res = 0;
        if (ql <= mid) res += querySum(2 * node, l, mid, ql, qr);
        if (qr > mid) res += querySum(2 * node + 1, mid + 1, r, ql, qr);
        return res;
    }

