class BookMyShow {
    private int n, m;
    private int[] treeMax;
    private long[] treeSum;
    private int[] used;
    private int firstAvailable = 0;

    public BookMyShow(int n, int m) {
        this.n = n;
        this.m = m;
        treeMax = new int[4 * n];
        treeSum = new long[4 * n];
        used = new int[n];
        build(1, 0, n - 1);
    }

    private void build(int node, int l, int r) {
        if (l == r) {
            treeMax[node] = m;
            treeSum[node] = m;
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        treeMax[node] = Math.max(treeMax[2 * node], treeMax[2 * node + 1]);
        treeSum[node] = treeSum[2 * node] + treeSum[2 * node + 1];
    }

    private void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            treeMax[node] = val;
            treeSum[node] = val;
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        treeMax[node] = Math.max(treeMax[2 * node], treeMax[2 * node + 1]);
        treeSum[node] = treeSum[2 * node] + treeSum[2 * node + 1];
    }

    private long querySum(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return treeSum[node];
        int mid = (l + r) / 2;
        long res = 0;
        if (ql <= mid) res += querySum(2 * node, l, mid, ql, qr);
        if (qr > mid) res += querySum(2 * node + 1, mid + 1, r, ql, qr);
        return res;
    }

    private int findFirst(int node, int l, int r, int maxR, int k) {
        if (treeMax[node] < k || l > maxR) return -1;
        if (l == r) return l;
        int mid = (l + r) / 2;
        int res = findFirst(2 * node, l, mid, maxR, k);
        if (res != -1) return res;
        return findFirst(2 * node + 1, mid + 1, r, maxR, k);
    }

    public int[] gather(int k, int maxRow) {
        int row = findFirst(1, 0, n - 1, maxRow, k);
        if (row == -1) return new int[]{};
        int col = used[row];
        used[row] += k;
        update(1, 0, n - 1, row, m - used[row]);
        return new int[]{row, col};
    }

    public boolean scatter(int k, int maxRow) {
        if (querySum(1, 0, n - 1, 0, maxRow) < k) return false;
        int row = firstAvailable;
        while (k > 0 && row <= maxRow) {
            int avail = m - used[row];
            int take = Math.min(k, avail);
            used[row] += take;
            k -= take;
            update(1, 0, n - 1, row, m - used[row]);
            if (used[row] == m) row++;
        }
        firstAvailable = row;
        return true;
    }
}

